APP_HELP = MappingProxyType({entry.id: entry for entry in APP_ENTRIES})
if len(APP_HELP) != len(APP_ENTRIES):
    raise ValueError('Duplicate Auralyn help ID')
if any(entry.steps for entry in APP_ENTRIES):
    raise ValueError('Product help must not execute shell commands')
